    public static function svg(string $name, string $class = 'h-6 w-6'): string
    {
        $d = self::PATHS[$name] ?? self::PATHS['arrow'];
        return '<svg xmlns="http://www.w3.org/2000/svg" class="' . $class . '" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="' . $d . '"/></svg>';
    }

    /** The logo's waveform as a scalable, optionally animated SVG. */
    public static function waveform(string $class = '', bool $animated = true): string
    {
        // Bar heights mirror the logo mark (tallest in the centre)
        $heights = [10, 22, 34, 48, 40, 62, 84, 100, 78, 56, 70, 44, 30, 20, 10];
        $n = count($heights);
        $w = 6;
        $gap = 8;
        $width = $n * $w + ($n - 1) * $gap;
        $out = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' . $width . ' 100" class="' . $class . '" aria-hidden="true" preserveAspectRatio="xMidYMid meet">'
            . '<defs><linearGradient id="wf-gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f5ecdd"/><stop offset=".45" stop-color="#ca9c6a"/><stop offset="1" stop-color="#8e6a45"/></linearGradient></defs>';
        foreach ($heights as $i => $h) {
            $x = $i * ($w + $gap);
            $y = (100 - $h) / 2;
            $style = $animated ? ' style="--d:' . round(($i % 5) * 0.35 + ($i * 0.07), 2) . 's;--s:' . (0.35 + (($i * 37) % 50) / 100) . '"' : '';
            $out .= '<rect class="' . ($animated ? 'wave-bar' : '') . '" x="' . $x . '" y="' . $y . '" width="' . $w . '" height="' . $h . '" rx="3" fill="url(#wf-gold)"' . $style . '/>';
        }
        return $out . '</svg>';
    }
